-- Step 3 of the Nightbane extraction plan: the core book's 25 Talents
-- (apps/character-creator/docs/surveys/nightbane-core.md). Printed 106-115.
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/zzzzzzzzzzzzz-nb-talents.sql
--
-- The `talents` table (migration 063, BOOK-INGEST-AUDIT F76) was built for these
-- rows and held none. Printed 107's alphabetical list names 25 - 21 Common and 4
-- Elite - and every one has a description, a Limitations line and a Cost line.
--
-- NAMES ARE THE LIST'S, as the spell and psionic imports took the index's: the
-- list prints `Shroud` where the heading prints `The Shroud`, and `Nightbringer`
-- where the cache's heading reads `Nighthringer` (an OCR b/h swap).
--
-- COSTS, read off each Cost line:
--   acquire_ppe  the permanent price. A flat integer on all 25.
--   ppe          the activation MINIMUM. 0 on the two whose Cost line says the
--                activation "varies as described above": Storm Maker and
--                Lord/Lady of the Wild. Their schedules are in ppe_note.
--   ppe_note     the rest of the schedule in a few words. Blank on exactly three
--                - Anti-Arcane, Mirror Sight, Soul Shield - the only clean pairs.
-- The shapes migration 063 counted hold: 10 level-gated (Lord/Lady at fourth);
-- form morphus 22, facade 1 (Reshape Facade), both 1 (Mirror Sight), and See
-- Truth, whose Limitations line states no form, NULL; five prerequisites.
--
-- RANGE, DURATION AND SAVING THROW are short readings of the Limitations line or
-- the description where the book puts them there; a Talent has no stat block of
-- its own for them, and NULL means the book does not state one.
--
-- CITATIONS ARE PRINTED FOLIOS. Swarm Self runs 113-115 across a full-page
-- illustration on 114; its tail and all of Lord/Lady of the Wild were read off
-- printed 115. The OCR's digit substitutions (`ID4`, `I mile`, `1 2`) are read as
-- the digits they can only be.

INSERT INTO talents
  (name, tier, acquire_ppe, ppe, ppe_note, min_character_level, form_required, prerequisite,
   source, source_book, system, range, duration, saving_throw, description, variant_note)
VALUES
  ('Anti-Arcane', 'common', 15, 20, NULL, 5, 'morphus', NULL, 'import', 'Nightbane RPG p.107', 'nightbane', NULL, 'One minute (4 melees)', NULL, 'When activating this Talent, the Nightbane is surrounded by an aura of black light (easily confused with the Shadow Shield described below). While this aura is in effect, the Nightbane is utterly invulnerable to the effects of magic! Any magical spell that can be resisted by a save against magic will have no effect on the character. Spells that must be dodged, or have no saving throw, will work normally. The Anti-Arcane will last one minute (4 melees), at which time it must be reactivated.', NULL),
  ('Borrow Morphus', 'common', 15, 15, 'plus 15 per additional minute', 5, 'morphus', NULL, 'import', 'Nightbane RPG p.108', 'nightbane', NULL, '4 melee rounds (one minute)', NULL, 'This rare power allows a Nightbane to assume the Morphus of another of his kind! The "other" Nightbane whose likeness is being copied suffers no ill effect other than the shock of seeing his double. The character gains the shape, all physical attributes, S.D.C. and hit points of the "borrowed" shape. He can also use any of the Talents possessed by the Nightbane he is imitating, but only abilities that the borrowing character knew the other possessed. Furthermore, the borrowing Nightbane cannot use his own Talents until he resumes his true form. He also uses his own combat skills (modified by the borrowed form''s attribute bonuses) and his normal skills - the Talent borrows only the other person''s physical body and does NOT include the character''s memories, knowledge, or insanities. The transformation lasts 4 melee rounds (one minute).', NULL),
  ('Darksong', 'common', 7, 5, 'plus 3 per +1 to the number needed to save', NULL, 'morphus', NULL, 'import', 'Nightbane RPG p.108', 'nightbane', 'Area use: 60 feet (18.3 m) radius', 'Stuns for 1D4 melee rounds', 'Roll 10 or higher (P.E. bonuses apply); +4 to save against the area use', 'The Nightbane can emit a piercing, deafening sound; it can be an inhuman howl, a mighty roar, an ultrasonic keening, or even electronic feedback, depending on the Nightbane''s Morphus. Targets must make a roll to save (P.E. bonuses apply); if they roll under a 10, they are stunned for 1D4 melee rounds. The attacker can raise the number needed to save by expending additional P.P.E.: +1 point per 3 P.P.E. The Darksong can be used against an area (60 feet/18.3 m radius); in that case, everyone in the area, friend or foe, must make a save, but they are at +4 to resist.', NULL),
  ('Doorway', 'common', 15, 2, '2 per mile of range; 40 plus 5 per mile to or from the Nightlands', 5, 'morphus', NULL, 'import', 'Nightbane RPG p.108', 'nightbane', '1 mile (1.6 km) per 2 P.P.E.', NULL, NULL, 'Creates a door of dark energy that leads to a specific location desired by the creator of it. Takes one melee round (15 seconds) of concentration. Range: To a location up to 1 mile (1.6 km) per 2 P.P.E. spent. The Nightbane must have been to the destination point at least once in his life, or he must have line of sight.', NULL),
  ('Darkwhip', 'common', 8, 4, 'more P.P.E. raises the whip''s damage', NULL, 'morphus', NULL, 'import', 'Nightbane RPG p.108', 'nightbane', '60 feet (18.3 m)', '4 melee rounds (one minute)', NULL, 'Creates tendrils of darkness that inflict supernatural damage with a P.S. equal to the amount of P.P.E. spent on creating them. Lasts for 4 melee rounds (one minute), after which they must be recreated. Range is 60 feet (18.3 m). The tendrils can have any shape, not limited to whips and tentacles, although those are the most common. The Darkwhip can be used to strike and also to entangle or disarm, provided those skills are known to the wielder.', NULL),
  ('Infectious Control', 'common', 20, 20, 'plus 20 per additional half hour; 5 per memory searched', 6, 'morphus', NULL, 'import', 'Nightbane RPG p.108-109', 'nightbane', NULL, 'One melee round; 30 minutes on a failed save (an hour at M.E. 7 or less)', 'Vs magic, again every 10 minutes; vs psionics against a memory search', 'This often repulsive Talent allows the Nightbane to take over a person by "infecting" him with a portion of his body. The manifestations of this power are varied. Some Nightbane shoot spines or needles that pierce the flesh of the target, allowing them to take over. Others create little "parasites" that burrow into the victim''s body. Biomechanicals often drill or shoot wires or microchips into the victim. Some Stigmata sufferers actually force-feed the victim some of their blood to infect them. Once the infection is complete (usually takes one melee round from the time the piece of the Nightbane has entered the body of the victim), the subject is controlled by the Nightbane for one melee round (15 seconds). At the end of the round, the victim can try to resist (save vs magic); if he fails the save, he is under the control of the Nightbane for 30 minutes. New saves are allowed every 10 minutes. While in control, the Nightbane can see, hear and experience everything his victim does while he acts as a puppeteer, controlling every word and movement of the victim. The main drawback is that the Nightbane has to split his concentration and attention between his own body and that of his victim. Thus, his attacks/actions per melee round are divided evenly between the two bodies. He has no initiative bonus, and combat bonuses and skill performance is reduced by half, unless he relinquishes his control over his puppet. The "infection" also allows the Nightbane to search the memories of his victim; one piece of information can be extracted by spending an additional 5 P.P.E. (and the victim gets a separate save to resist against the intrusion; this save is against psionic attack rather than magic). Each "memory search" takes 1D6 minutes and is limited to one small bit of information at a time. Note: Victims who have an M.E. of 7 or less are controlled for an hour at a time rather than the usual half an hour.', NULL),
  ('Lightning Rider', 'common', 15, 10, '10 per minute; 5 more per extra 1D6 S.D.C. damage', NULL, 'morphus', NULL, 'import', 'Nightbane RPG p.109', 'nightbane', NULL, 'Per minute maintained', NULL, 'The Nightbane becomes a being of pure electrical energy! Unless a great deal of P.P.E. is spent, the electrical charge is weak and does not inflict damage. However, while in electrical form, the Nightbane can travel through conductive materials at enormous speeds. When the power is activated, the Nightbane disappears in a flash of electricity and "leaps" onto the nearest conductive material (metal and exposed wires works best). If no such material is around, the Nightbane appears to become a small pool of sparks, or a small crackling lightning ball that crawls around at a speed of 8. With the invention of the telephone and electrical wires, this Talent came into its own and enables Nightbane to travel from one corner of the world to the next in a matter of minutes through them. Some Nightbane become extremely proficient in navigating through telephone exchanges. The easiest way, of course, was to call the place one wished to travel to and then travel through the phone lines and jump out of the receiver! With the advent of computers and the Internet, this power has become even more influential. A character with Computer Operations can understand the information superhighway and hitch rides on modem calls. A character with Computer Programming can become the ultimate hacker!', NULL),
  ('Mirror Sight', 'common', 5, 2, NULL, NULL, 'both', NULL, 'import', 'Nightbane RPG p.109', 'nightbane', NULL, '10 minutes per level of experience', NULL, 'This and other mirror related talents and natural abilities give the archaic name of "looking glass" great new significance when dealing with the Nightbane and the Nightlords. This Talent enables the Nightbane to see the other side of a mirror, into the Nightlands, and vice versa, as if it were a window. A mirror or any highly reflective surface (glass, polished metal, a quiet body of water) must be available. The character can only see what the mirror image faces in the Nightlands, and vice versa. Some Nightlands creatures may sense they are being "looked at" and could cross over to confront or attack the "peeper" (see the Nightlands Section for more information).', NULL),
  ('Mirror Search', 'common', 10, 15, 'for a 10 mile area; plus 5 per additional 10 miles (16 km)', NULL, 'morphus', 'Mirror Sight', 'import', 'Nightbane RPG p.110', 'nightbane', '10 mile (16 km) area, more with additional P.P.E.', NULL, NULL, 'The Nightbane is able to see through the mirror closest to the person or object he seeks. This is an area effect Talent that effectively scans a 10 mile radius (more if additional P.P.E. are expended) in search of the person or item sought. This does not mean that the nearest mirror will reveal the target of the search, but the closest area and mirror to it. For example: Searching for a kidnapped friend, the mirror search may reveal the image of a bathroom in a hotel. The name of the hotel is visible from the hanging towels, which may be enough to figure out, at least roughly, where the person is. Or there may actually be a mirror in the hotel room (there usually is) that shows the Nightbane''s friend bound to a chair and being interrogated by two thugs and a Hound. Note: Both mirror sight and mirror search show only images, not sound - it''s like looking through the glass of a closed window into the room or area where the mirror is located (which may show parts of other rooms or a hallway, things outside the windows in that room, etc.). Covering a mirror with a blanket, towel, or other covering will prevent a character from effectively using mirror sight and mirror search, because all the mirror will show is that it is covered. However, it does not prevent a Nightlord or other so empowered being from traveling and entering that room through the covered mirror, even if wrapped snugly - the monster tears right through the cloth or tarp. However, painting the mirror will prevent such passage as well as the use of the mirror as a window.', NULL),
  ('Nightbringer', 'common', 5, 2, 'plus 2 per extra 10 feet (3 m) of diameter', NULL, 'morphus', NULL, 'import', 'Nightbane RPG p.110', 'nightbane', NULL, NULL, NULL, 'Absorbs light around the Nightbane, creating an area of darkness equal to 10 feet (3.0 m) in diameter per every 2 P.P.E. spent. The power also absorbs energy attacks, except Shadow Blast, Darkwhip and other darkness-based attacks and magic. People caught in the unnatural darkness are at -6 to strike, parry and dodge, and -4 on their perception rolls (penalties are half for creatures with nightvision).', NULL),
  ('Premonition', 'common', 2, 2, 'plus 2 whenever a premonition comes spontaneously', NULL, 'morphus', NULL, 'import', 'Nightbane RPG p.110', 'nightbane', NULL, NULL, NULL, 'Gives the character feelings and visions about the future, often at unexpected times (ultimately, when the Game Master decides the character should get a vision, he does) or at moments of crisis. For the most part, a premonition will give the character a feeling that something good, bad or dangerous is going to happen soon, or at some particular place, or to some particular person. These feelings are just that, and do not come with any dreams or images. "Visions" on the other hand, are usually images and/or short dream sequences that are accompanied by "feelings." These images are often symbolic omens and can be cryptic (but G.M.s, not too cryptic) and may give some hints of things to come. For example: The Nightbane may have a reoccurring vision about a man or Nightlord, or minion slaughtering innocent people, his friends or even himself. The murderous figure is always in shadow so his features cannot be seen, but the vision always ends with the image of a stylized eagle. Then one day, the Nightbane meets a person with a tattoo of that eagle, indicating that this person is the culprit, but not always. The tattoo could be the symbol of a gang or cult worn by all its members in one fashion or another. Or it could be the logo for a corporation, or the emblem for a special police squad, the hilt of a magic sword, a statue, the cover of a book, and so on. At any rate, it gives our hero some warning about danger and who or what might be involved.', NULL),
  ('Reshape Facade', 'common', 12, 6, 'plus 4 per additional hour', 3, 'facade', NULL, 'import', 'Nightbane RPG p.110-111', 'nightbane', NULL, NULL, NULL, 'Although contemptuously called the Facade, the Nightbane''s human form is as unique and real to him or her as the superhuman Morphus. Nightbane with this Talent can temporarily alter the shape of the Facade, changing the features, hair color and even the size of their human form. The more extensive the change, the more P.P.E. the transformation will cost. Imitating a particular person is possible, but very difficult to get right (20% plus I.Q. bonus, plus 3% per level of experience).', NULL),
  ('See Truth', 'common', 3, 2, 'plus 4 per +1 to the save number, to 18', NULL, NULL, NULL, 'import', 'Nightbane RPG p.111', 'nightbane', 'Line of sight up to 300 feet (91.4 m)', NULL, 'Vs magic (12 or higher, raisable to 18)', 'Every time this power is activated, the Nightbane will be able to see the true nature of one person or object. In the case of Nightbane, the character will be able to see the target''s true Facade and Morphus forms, superimposed on one another. The alignment of the target can also be seen by the character; applicable to humans and Nightbane (in the latter case, counts as a separate use of this Talent). Furthermore, it will reveal strong magic emanations, the undead/vampires, serious illness, and strong emotions (hatred when the person is smiling and being nice, etc.); all considered aspects of the soul and/or personality of the target. The subject saves against magic (12 or higher) to resist revealing the truth. The Nightbane can increase the difficulty of the save by expending more P.P.E.: every additional 4 P.P.E. raises the save number by +1 (maximum of 18, for 24 P.P.E.).', NULL),
  ('Shadow Shield', 'common', 7, 2, '20 S.D.C. per 2 P.P.E.; at most 4 P.P.E. per level', NULL, 'morphus', NULL, 'import', 'Nightbane RPG p.111', 'nightbane', NULL, '30 minutes per level of experience, or until its S.D.C. is used up', NULL, 'Creates a force field of dark energy around the Nightbane, providing 20 S.D.C. per 2 P.P.E. spent (P.P.E. spent cannot exceed 4 per level of experience). The Shadow Shield completely surrounds the character, protecting him from toxic gases, disease, punches, bullets, heat, fire, and similar dangers as long as it remains in force; it is the shield that takes the damage inflicted by such attacks.', NULL),
  ('Shadow Slide', 'common', 8, 10, '10 per minute; plus 2 per pound (0.45 kg) carried', NULL, 'morphus', NULL, 'import', 'Nightbane RPG p.111', 'nightbane', NULL, 'Per minute maintained', NULL, 'The Nightbane must be in Morphus form for this power to work. The character becomes an insubstantial shadow, or, more accurately, like one of those mirages you can see on a paved road during a sunny day - a flickering shadow that seems to sink into the earth and fades away as if it never was. While in this two-dimensional form, the Nightbane can slither along walls or across the ground, virtually invisible and able to slide through any opening, no matter how narrow (only air tight containers will prevent the shadow-slider from coming through). The Nightbane''s clothing and small personal effects are transformed automatically; additionally, he can carry objects at an additional P.P.E. cost (2 P.P.E. per pound/0.45 kg of weight).', NULL),
  ('Shadow Blast', 'common', 5, 1, '1 per 1D4 S.D.C. of damage; at most 4 per level', NULL, 'morphus', NULL, 'import', 'Nightbane RPG p.111', 'nightbane', '500 feet (152 m)', NULL, NULL, 'Fires a black energy bolt that does 1D4 S.D.C. for every point of P.P.E. spent on it, so 10 P.P.E. would result in a 1D4x10 S.D.C. bolt, and so on.', NULL),
  ('Sharing the Flesh', 'common', 2, 8, 'healing the comatose: 24 P.P.E. and 100 S.D.C./hit points', NULL, 'morphus', NULL, 'import', 'Nightbane RPG p.112', 'nightbane', NULL, NULL, NULL, 'This is a strange and horrific healing spell. The Nightbane touches an injured person to magically transfer the other person''s wounds, injury and pain to himself. The person being healed falls into a coma or sleep that lasts 1D4 melee rounds and then awakens completely well. The effect is often gruesome, with nasty wounds spontaneously appearing on the Nightbane as the subject heals. The Nightbane can transfer as much damage as he or she can tolerate, which may be a little amount to all. This is actually a painful sacrifice on the part of the Nightbane as he/she heals as normal - fortunately, these creatures heal rapidly compared to humans.', NULL),
  ('Shroud', 'common', 12, 10, '10 per minute', NULL, 'morphus', NULL, 'import', 'Nightbane RPG p.112', 'nightbane', NULL, 'Per minute maintained; ends when the Nightbane attacks', NULL, 'This powerful Talent enables a Nightbane to become invisible and noiseless to both the normal vision and senses as well as to electronic devices like cameras, motion detectors, heat sensors, etc. This ability can be used selectively, enabling some people to see the character while others can''t. Vengeful Nightbane have been known to drive a human insane by pursuing him in plain sight, invisible to everyone else. The victim''s cries for help would be useless, for nobody else can see the monster threatening him! The power is very expensive to maintain for long periods of time (10 P.P.E. per minute). Also, the moment the Nightbane attacks anybody (he can threaten, scream or make gestures all he wants), the Talent stops working and he becomes visible for all to see. Likewise, a Nightbane actively engaged in combat or other activity, or standing in plain sight, cannot activate this Talent to disappear. First, he must get out of sight.', NULL),
  ('Soul Shield', 'common', 6, 4, NULL, NULL, 'morphus', NULL, 'import', 'Nightbane RPG p.112', 'nightbane', NULL, 'One hour', 'Mind readers save vs psionics each melee round', 'Protects against mental attacks/probes and the See Truth Talent. The Soul Shield acts like a psychic mind block, preventing most means of magical or psionic probes from intruding into the Nightbane''s mind. More importantly, while the Soul Shield is up, any spell or power that tries to control or dominate the Nightbane''s mind will automatically fail. Those who attempt to read the protected character''s mind will see only a pool of utter darkness. The mind reader/psychic will find it very difficult to pry himself from that darkness (a save versus psionics is necessary; roll every melee round), and until he does, he will be unable to do anything other than stare vacantly into space.', NULL),
  ('Splittin'' Image', 'common', 15, 20, 'for one hour; plus 10 per additional hour', 5, 'morphus', NULL, 'import', 'Nightbane RPG p.112', 'nightbane', NULL, 'One or more hours, by P.P.E. spent', NULL, 'This powerful ability enables the Nightbane to separate his Facade and Morphus forms and act normally in both of them! The Nightbane in effect, becomes two people. The character is aware of what both sides are doing, but his consciousness must be focused on one form or the other (he can switch viewpoints at will). The form his consciousness is focused on acts normally; the other appears to lapse into a trance-like state and is at -2 on all combat and perception rolls, has half the normal attacks per melee round, and is at -40% to perform any skills.', NULL),
  ('Storm Maker', 'common', 20, 0, 'varies: 5 minor to 80 total upheaval; doubles per extra mile of radius', 5, 'morphus', NULL, 'import', 'Nightbane RPG p.112-113', 'nightbane', 'One mile (1.6 km) radius', 'One hour, after 1D6x10 minutes to take effect', NULL, 'This powerful talent enables the Nightbane to control the weather. Rain, winds and the temperature can be altered. The more extreme the changes and the greater the area affected, the more P.P.E. the character must spend. This talent is particularly powerful because two or more Nightbane who know it can combine their efforts (and P.P.E.) to produce an even more powerful effect. There are legends of ancient Nightbane groups sending hurricanes and tornadoes against people who offended or injured them. The P.P.E. cost varies; the effects take 1D6x10 minutes to manifest, and then lasts one hour. At the end of the hour, the same amount of P.P.E. must be spent to keep it going or it fades away. Some guidelines are given below: A minor change in existing weather conditions like raising the wind by up to 5 mph (8 kmph), increasing or decreasing cloudiness, intensifying already existing rain, raising or lowering overall temperature by 4 degrees Fahrenheit: 5 P.P.E. A moderate change of weather conditions like starting rain on an overcast day, turning a downpour into a storm or vice versa, raising or lowering overall temperature by 10 degrees Fahrenheit: 10 P.P.E. Sudden, major change in weather like starting rain during a clear, sunny day, stopping a downpour, or creating a major thunder or electrical storm during a rainy day, raising or lowering overall temperature by 20 degrees Fahrenheit: 20 P.P.E. Extreme changes in weather like creating a fog, or starting a hailstorm or electrical storm during a clear, sunny day - or turning a storm into a sunny day, turning a thunderstorm into a tropical storm with near-hurricane winds (70 mph/112 kmph), raising or lowering overall temperature by 30 degrees Fahrenheit: 40 P.P.E. Total upheaval in weather such as starting a hurricane or tornado from scratch (90+ mph/144 km winds), create a blinding snowstorm, dissipating a hurricane or terrible storm, raising or lowering overall temperature by 50 degrees Fahrenheit: 80 P.P.E. The base area affected has a radius of one mile (1.6 km). Each additional mile of radius doubles the previous P.P.E. cost. For example: causing a moderate change in the weather costs 10 P.P.E. for one mile/1.6 km, 20 P.P.E. for two miles/3.2 km, 40 P.P.E. for three miles/4.8 km, and 80 P.P.E. for a four mile/6.4 km radius.', NULL),
  ('Bloodbath', 'elite', 15, 8, 'and 1D6 S.D.C. damage to the user', 3, 'morphus', 'At least one characteristic from the Stigmata Table', 'import', 'Nightbane RPG p.113', 'nightbane', NULL, '1D4 melee rounds', 'Vs non-lethal poison each round; Horror Factor 12', 'This grotesque power allows the Nightbane to use his own blood to suffocate victims. A stream of blood pours from the character (this inflicts 1D6 points of damage to the character, activating the Talent). The Nightbane is at +3 to strike with it. On a successful hit, the blood will rush into the victim''s nose and throat, and cause him to choke! While drowning in blood, the victim is at -2 on all combat actions and is unable to use spells, Talents or any skill that requires concentration. The blood remains alive for 1D4 melee rounds, inflicting 2D6 points of damage at the end of each melee round. A successful save versus non-lethal poison will avoid damage for that round, but the penalties remain. Additionally, a victim unfamiliar with that attack must save versus a Horror Factor of 12 to avoid panicking. If panicked, the penalties for the victim are doubled.', NULL),
  ('Deus Ex Machina (Machine Control)', 'elite', 12, 4, 'plus 6 per extra minute, or 20 per extra 100 foot (30.5 m) radius', 3, 'morphus', 'At least one biomechanical characteristic', 'import', 'Nightbane RPG p.113', 'nightbane', '300 feet (91.4 m)', 'One minute', NULL, 'The Nightbane can control machines from cars to microwaves, to lamps or weapons. One device can be controlled for every three points of I.Q. he has (thus, a Nightbane with an I.Q. of 13 could control 4 machines). The machines can then be made to do anything within their capabilities. For example, a lamp can turn itself on or off, but nothing else. A car or a motorcycle could start its motor and ride off (until it left the range of the effect). While the Nightbane can control several machines, only one of them can be directly controlled on an action-by-action basis. The remaining mechanisms can be given a general order for the rest of the round. Example: The aforementioned Nightbane is trapped in a house by a number of NSB agents. Trying to create a diversion, he activates Deus Ex Machina and takes control of four machines, including a desk-top computer, a laser printer, a lawn mower just outside the house, and a lamp on the desk. He first orders the office machines to start the diversion, the lamp will turn itself on and off for a melee round, the computer will start making noise at the top of its Soundblaster speakers, and the laser printer will start spitting blank pieces of paper. As the NSB are distracted by the noises coming from the office, the Nightbane takes full control of the lawn mower and sends it roaring into their midst! As the agents shoot the hapless machine to pieces, the Nightbane quietly slips out the back. In a pinch, the character can also seize control of guns and even explosive devices to prevent them from firing (or detonating) or to shoot (explode) whether the user wants them to or not.', NULL),
  ('Swarm Self', 'elite', 15, 10, 'for the first two minutes; plus 10 per additional two minutes', NULL, 'morphus', 'At least one characteristic from the Animal or Insect Form Table', 'import', 'Nightbane RPG p.113-115', 'nightbane', 'Self; unrestricted once a swarm', NULL, NULL, 'Causes the Nightbane''s body to separate into 2D4x10 tiny animals of the same animal type as the character (see prerequisites, below). The Nightbane controls this swarm and is aware of everything they do or see. Each swarm member has 5 S.D.C. and 1 Hit Point. In combat, they do 1 point of S.D.C. damage individually or 5D6 S.D.C. from a group or swarm of 10 or more every melee round (all 10 attack one target; several groups of 10 can attack different targets). The swarmlings have the same combat bonuses as the Nightbane when attacking individually; they are small targets, requiring a called shot at -5 to hit! If attacking as a group, each group of 10 will automatically swarm over a target in 3-5 seconds (equivalent to a melee attack/action) and inflict the damage at the end of each melee round. Attacks on the swarm have no modifiers to hit; a swarm of 10 critters will have 50 S.D.C. and 10 Hit Points. If the swarm takes more than half its S.D.C. damage, it means that half of the critters are dead, damage is reduced to 2D6. When all the S.D.C. is depleted, this means that only two swarmlings remain, and they attack and defend normally (see above). The hit point (not S.D.C.) damage taken by the swarm carries over to the Nightbane''s hit points after the swarm is destroyed or recalled. The swarmlings do not regenerate damage and the character must switch back to his normal Morphus form and limp away. At least two of the swarmlings must be present for the Nightbane to rebuild himself, but most retreat and reform when reduced to 10 or 15. If all are destroyed, then the Nightbane is slain.', NULL),
  ('Lord/Lady of the Wild (Animal Control)', 'elite', 15, 0, 'varies: calling 2; per large animal or ten small, 1 minor, 5 dangerous, 10 suicidal', 4, 'morphus', 'At least one characteristic from the Animal Form Table', 'import', 'Nightbane RPG p.115', 'nightbane', 'One mile (1.6 km) to summon, 500 feet (152 m) to control', '15 minutes', NULL, 'The Nightbane gains mastery over any animal species he/she is associated with; thus, a wolf-life Nightbane will be able to control wolves and any canine animal, while a bird-like character would gain powers over all birds. The power has variable range and effects, depending on the amount of P.P.E. the Nightbane spends. Simple commands like "Come here," "Attack this man," "Go," or "Make a lot of noise" will be readily heeded. A character with this power can also make animals behave in unnatural ways, like attacking armed men, something most animals will never do, dance in circles, leap through a wall of fire, etc., but this will cost more P.P.E. Some guidelines are described below: Calling animals: Any animals of the appropriate species will come from up to a one mile (1.6 km) radius per level of experience: Costs 2 P.P.E. Once they get there, the animals will revert to normal unless new commands are given. Minor, non-dangerous actions: Like making noise, hiding, fluttering about, or acting in fairly normal ways: Costs 1 P.P.E. per large animal or per group of up to ten small animals (rat/pigeon-sized or smaller). Dangerous actions: Threatening humans, bite/attack, leap at, block or otherwise hindering armed humans, or behavior that goes against the animal''s normal behavior (asking a nocturnal animal to operate in the daytime, etc.): Costs 5 P.P.E. per large animal or per group of up to ten small animals. Suicidal actions: Recklessly attacking humans or supernatural beings, intercepting vehicles (a flock of birds can bring down a plane by flying into its engines), fight to the death, and other suicidal or utterly unnatural acts: Costs 10 P.P.E. per large animal or per group of up to ten small animals.', NULL);

-- Read the result back. This batch asserts its OWN rows and nothing else.
SELECT 'twenty-five nightbane Talents' AS assertion, count(*) AS got, 25 AS want
  FROM talents WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%';

SELECT 'four of them Elite' AS assertion, count(*) AS got, 4 AS want
  FROM talents WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%' AND tier = 'elite';

SELECT 'ten are level-gated' AS assertion, count(*) AS got, 10 AS want
  FROM talents WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%' AND min_character_level IS NOT NULL;

SELECT 'twenty-two are Morphus-only' AS assertion, count(*) AS got, 22 AS want
  FROM talents WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%' AND form_required = 'morphus';

SELECT 'five carry a prerequisite' AS assertion, count(*) AS got, 5 AS want
  FROM talents WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%' AND prerequisite IS NOT NULL;

SELECT 'three clean cost pairs, two varying activations' AS assertion, count(*) AS got, 5 AS want
  FROM talents WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%'
   AND ((ppe_note IS NULL AND name IN ('Anti-Arcane', 'Mirror Sight', 'Soul Shield'))
     OR (ppe = 0 AND ppe_note LIKE 'varies%' AND name IN ('Storm Maker', 'Lord/Lady of the Wild (Animal Control)')));

SELECT 'every one carries its description and its permanent price' AS assertion, count(*) AS got, 25 AS want
  FROM talents WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%' AND length(description) > 140 AND acquire_ppe > 0;

